using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using System.IO;using System.Linq;
namespace IntegratedCampaign.EditorTools {
[InitializeOnLoad]public static class CampaignSetup {
 static CampaignSetup(){EditorApplication.update+=Poll;}
 static void Poll(){string p="Temp/campaign-command.txt";if(!File.Exists(p)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;string c=File.ReadAllText(p).Trim();File.Delete(p);try{if(c=="apply")Apply();if(c=="openmenu")EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");if(c=="menu"){EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");EditorApplication.isPlaying=true;}if(c.StartsWith("size ")){var parts=c.Split(' ');var type=typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView");var window=EditorWindow.GetWindow(type);type.GetMethod("SetCustomResolution",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).Invoke(window,new object[]{new Vector2(int.Parse(parts[1]),int.Parse(parts[2])),"Campaign check"});window.Repaint();}if(c=="shot")Capture();if(c=="previewship")CampaignFlow.Instance.Go(CampaignPhase.IntroVoyage);if(c=="settings")Object.FindFirstObjectByType<CampaignMenu>().SendMessage("OpenSettings",true);if(c=="prefstest")new GameObject("Preference test").AddComponent<CampaignPreferenceVerification>();if(c=="deliverytest")new GameObject("Delivery test").AddComponent<CampaignDeliveryVerification>();if(c=="test"){if(!Object.FindFirstObjectByType<CampaignVerification>())new GameObject("Campaign verification").AddComponent<CampaignVerification>();}if(c=="stop")EditorApplication.isPlaying=false;File.WriteAllText("Tools/CampaignIntegration/status.txt",c+" OK");}catch(System.Exception e){File.WriteAllText("Tools/CampaignIntegration/status.txt",e.ToString());Debug.LogException(e);}}
 static void Capture(){ScreenCapture.CaptureScreenshot("Tools/CampaignIntegration/game.png");var cam=Camera.main;var rt=new RenderTexture(1600,900,24);cam.targetTexture=rt;Canvas.ForceUpdateCanvases();cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes("Tools/CampaignIntegration/camera.png",t.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}
 static Sprite S(string n)=>AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Campaign/Resources/Campaign/"+n+".png");
 static GameObject[] Pool(params string[] names)=>AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Enemies"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<GameObject>).Where(p=>names.Contains(p.name)).ToArray();
 static RectTransform R(string name,Transform parent,Vector2 at,Vector2 size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=Vector2.one*.5f;r.anchoredPosition=at;r.sizeDelta=size;return r;}
 static TMPro.TextMeshProUGUI Text(string name,Transform parent,Vector2 at,Vector2 size,string value,TMPro.TMP_FontAsset font,float points){var r=R(name,parent,at,size);var t=r.gameObject.AddComponent<TMPro.TextMeshProUGUI>();t.font=font;t.fontSize=points;t.text=value;t.color=new Color(1,.94f,.77f);t.alignment=TMPro.TextAlignmentOptions.Center;t.raycastTarget=false;return t;}
 static void BindCards(ShipUIManager manager,TMPro.TMP_FontAsset font){if(manager.levelUpOverlay)return;var root=new GameObject("Existing upgrades • card display",typeof(RectTransform),typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler),typeof(UnityEngine.UI.GraphicRaycaster));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;root.GetComponent<Canvas>().sortingOrder=2200;var scale=root.GetComponent<UnityEngine.UI.CanvasScaler>();scale.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1920,1080);scale.screenMatchMode=UnityEngine.UI.CanvasScaler.ScreenMatchMode.Expand;
 var overlay=R("Upgrade choice",root.transform,Vector2.zero,new Vector2(1500,780));var back=overlay.gameObject.AddComponent<UnityEngine.UI.Image>();back.sprite=S("settings");back.type=UnityEngine.UI.Image.Type.Sliced;manager.levelUpOverlay=overlay.gameObject;manager.levelUpTitle=Text("Level",overlay,new Vector2(0,300),new Vector2(1200,70),"Gemi geliştirmesi",font,38);manager.levelUpSubtitle=Text("Instructions",overlay,new Vector2(0,230),new Vector2(1200,60),"Bir geliştirme seç",font,27);
 manager.cardButtons=new UnityEngine.UI.Button[3];manager.cardTierBadges=new UnityEngine.UI.Image[3];manager.cardTierTexts=new TMPro.TextMeshProUGUI[3];manager.cardTitles=new TMPro.TextMeshProUGUI[3];manager.cardDescs=new TMPro.TextMeshProUGUI[3];manager.cardIcons=new UnityEngine.UI.Image[3];
 for(int i=0;i<3;i++){var card=R("Upgrade card "+i,overlay,new Vector2((i-1)*440,-30),new Vector2(410,420));var image=card.gameObject.AddComponent<UnityEngine.UI.Image>();image.sprite=S("settings");image.type=UnityEngine.UI.Image.Type.Sliced;manager.cardButtons[i]=card.gameObject.AddComponent<UnityEngine.UI.Button>();manager.cardButtons[i].targetGraphic=image;manager.cardTierBadges[i]=R("Tier badge",card,new Vector2(0,125),new Vector2(160,45)).gameObject.AddComponent<UnityEngine.UI.Image>();manager.cardTierTexts[i]=Text("Tier",card,new Vector2(0,125),new Vector2(160,45),"I",font,25);manager.cardTitles[i]=Text("Title",card,new Vector2(0,45),new Vector2(330,100),"",font,29);manager.cardDescs[i]=Text("Description",card,new Vector2(0,-90),new Vector2(330,150),"",font,24);}
 overlay.gameObject.SetActive(false);EditorUtility.SetDirty(manager);
 }

 public static void Apply(){if(EditorApplication.isPlaying)throw new System.Exception("Stop play first");var original=SceneManager.GetActiveScene().path;EditorSceneManager.SaveOpenScenes();
 foreach(string p in Directory.GetFiles("Assets/Campaign/Resources/Campaign","*.png")){var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Single;ti.filterMode=FilterMode.Point;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.mipmapEnabled=false;ti.alphaIsTransparency=true;ti.spritePixelsPerUnit=100;ti.maxTextureSize=2048;string n=Path.GetFileNameWithoutExtension(p);if(n.StartsWith("flag_")){var settings=new TextureImporterSettings();ti.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2(.15625f,.02f);settings.spriteMeshType=SpriteMeshType.FullRect;ti.SetTextureSettings(settings);}if(n=="button"||n=="button_hover"||n=="button_pressed")ti.spriteBorder=new Vector4(95,55,95,55);if(n=="settings")ti.spriteBorder=new Vector4(100,100,100,100);if(n=="title")ti.spriteBorder=new Vector4(160,70,160,70);ti.SaveAndReimport();}
 var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var camera=new GameObject("Main Camera",typeof(Camera),typeof(AudioListener));camera.tag="MainCamera";camera.transform.position=new Vector3(0,0,-10);camera.GetComponent<Camera>().orthographic=true;new GameObject("Main menu").AddComponent<CampaignMenu>();EditorSceneManager.SaveScene(scene,"Assets/Scenes/MainMenu.unity");
 scene=EditorSceneManager.OpenScene("Assets/Scenes/ShipScene 1.unity");var ship=Object.FindFirstObjectByType<ShipController>();var d=ship.GetComponent<ShipCampaignDirector>();if(!d)d=ship.gameObject.AddComponent<ShipCampaignDirector>();d.townSprite=S("town");d.harborSprite=S("harbor");d.smallFish=Pool("Enemy_Yellow_Fish","Enemy_Pink_Fish","Enemy_Blue_Fish");d.sharks=Pool("Enemy_Shark","Enemy_SharkTopDown");d.whales=Pool("Enemy_Whale");d.flagFrames=Enumerable.Range(0,4).Select(i=>S("flag_"+i)).ToArray();var ocean=Object.FindFirstObjectByType<InfiniteOcean>();ocean.worldSpaceWater=true;ocean.oceanTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Sprites/ShipWaterProcessed/Ocean_Seamless.png");ocean.repeatSize=new Vector2(80,60);var sr=ocean.GetComponent<SpriteRenderer>();sr.sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Sprites/ShipWaterProcessed/Ocean_Seamless.png");sr.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/ShipWater/CalmOcean.mat");sr.sortingOrder=-100;sr.drawMode=SpriteDrawMode.Simple;var anim=ocean.GetComponent<Animator>();if(anim)anim.enabled=false;
 var hud=Object.FindFirstObjectByType<ShipHUDController>();if(hud){var font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>("Assets/Campaign/Pixelify SDF.asset");if(!font){font=TMPro.TMP_FontAsset.CreateFontAsset(AssetDatabase.LoadAssetAtPath<Font>("Assets/Campaign/Resources/Campaign/PixelifySans.ttf"));AssetDatabase.CreateAsset(font,"Assets/Campaign/Pixelify SDF.asset");AssetDatabase.AddObjectToAsset(font.material,font);foreach(var atlas in font.atlasTextures)AssetDatabase.AddObjectToAsset(atlas,font);}hud.hudFont=font;hud.ship=ship;hud.health=ship.GetComponent<PlayerHealth>();hud.upgradeProgress=Object.FindFirstObjectByType<ShipUIManager>();var toggle=hud.GetComponentInChildren<OrbRewardToggleView>(true);if(toggle){toggle.owner=null;toggle.shipProgress=hud.upgradeProgress;EditorUtility.SetDirty(toggle);}hud.RefreshAll();EditorUtility.SetDirty(hud);}BindCards(Object.FindFirstObjectByType<ShipUIManager>(),hud?hud.hudFont:null);var coast=GameObject.Find("Campaign coast and harbor");if(coast)Object.DestroyImmediate(coast);d.BuildHarbor();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
 var list=new[]{"Assets/Scenes/MainMenu.unity","Assets/Scenes/UnderwaterWorld.unity","Assets/Scenes/ShipScene 1.unity"}.Select(p=>new EditorBuildSettingsScene(p,true)).ToList();list.AddRange(EditorBuildSettings.scenes.Where(s=>!list.Any(t=>t.path==s.path)&&File.Exists(s.path)));EditorBuildSettings.scenes=list.ToArray();if(!string.IsNullOrEmpty(original))EditorSceneManager.OpenScene(original);
 }
}
}
